function saveVisit(){const now=Date.now();if(entered){count('minutes',(now-lastVisitSave)/60000);}lastVisitSave=now;}

function setupInput(){
  const surface=renderer.domElement,pointers=new Map();let down=null,lastPinch=0,drag=false;
  const activity=()=>{lastInput=performance.now();$('#modebar').classList.remove('dim');};
  document.addEventListener('pointerdown',activity,{passive:true});document.addEventListener('pointermove',activity,{passive:true});document.addEventListener('keydown',activity);
  surface.addEventListener('pointerdown',e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});surface.setPointerCapture(e.pointerId);down={x:e.clientX,y:e.clientY};drag=false;lastPinch=0;});
  surface.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;const old=pointers.get(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const[a,b]=[...pointers.values()],d=Math.hypot(a.x-b.x,a.y-b.y);if(lastPinch)cameraDistance=clamp(cameraDistance-(d-lastPinch)*.025,2.5,14);lastPinch=d;drag=true;return;}if(!down)return;if(Math.hypot(e.clientX-down.x,e.clientY-down.y)>5)drag=true;if(drag){const dx=e.clientX-old.x,dy=e.clientY-old.y;if(fireMode)fireMode.angle=clamp(fireMode.angle-dx*.004,-Math.PI*25/180,Math.PI*25/180);else{cameraYaw-=dx*.005;cameraPitch=clamp(cameraPitch+dy*.003,.12,1.15);}}});
  surface.addEventListener('pointerup',e=>{pointers.delete(e.pointerId);if(!drag&&!pointers.size&&entered&&!modal.current&&!propMode&&mode==='wander')pick(e);down=null;});surface.addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);down=null;});
  surface.addEventListener('wheel',e=>{e.preventDefault();cameraDistance=clamp(cameraDistance+e.deltaY*.008,2.5,14);activity();},{passive:false});
  /* 한글 입력 상태에서는 e.key가 'ㅈ'·'Process'가 되므로 실제 자판 위치(e.code)로 읽는다 */
  const keyName=e=>{const c=e.code||'';if(c.startsWith('Key'))return c.slice(3).toLowerCase();if(/^(Digit|Numpad)\d$/.test(c))return c.slice(-1);if(c==='Space')return ' ';return (e.key||'').toLowerCase();};
  /* Tab으로 단추를 고른 사람은 스페이스로 그 단추를 누른다. 마우스를 쓰면 다시 스페이스=절하기 */
  let tabbed=false;document.addEventListener('pointerdown',()=>{tabbed=false;},true);
  document.addEventListener('keydown',e=>{if(e.key==='Tab')tabbed=true;const typing=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||tabbed&&e.code==='Space'&&!!e.target.closest?.('button,a[href]');if(e.key==='Escape'){if(e.isComposing)return;e.preventDefault();/* 꾹 눌러 자동 반복된 Esc는 '한 번 더 누르기'로 치지 않는다 */if(e.repeat)return;if(death&&typing){e.target.blur();return;}escape();return;}if(typing)return;if(modal.current)return;
    if(propMode){const k=keyName(e);if(k==='q'){if(!e.repeat)openActivities();return;}if([' ','arrowup','arrowdown','arrowleft','arrowright','w','s'].includes(k)){e.preventDefault();if(!e.repeat)propMode==='moktak'?strikeMoktak():advanceBeads(k==='arrowup'||k==='w'?-1:1);}return;}
    if(!entered||mode==='rest'||mode==='exit')return;
    /* 앉기·불멍·절하기 중에도 이동 키를 누르면 그 활동을 끝내고 바로 걷는다 */
    const k=keyName(e);if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k)){e.preventDefault();if(mode==='death')return;if(fireMode)stopFire();else if(mode!=='wander'||busy)stopActivity();stopWalk();keys.add(k);return;}
    if([' ','1','e'].includes(k)){e.preventDefault();spaceHeld=true;if(!e.repeat)bow();}else if(!e.repeat){if(k==='3')gassho();if(k==='4')startFire();if(k==='5')openProp('moktak');if(k==='2')openProp('beads');if(k==='m')openMap();if(k==='q')openActivities();if(k==='h')openControls();if(k==='f'&&nearestSpot)interact(nearestSpot.id);}
  });
  document.addEventListener('keyup',e=>{const k=keyName(e);keys.delete(k);if([' ','1','e'].includes(k))spaceHeld=false;});document.addEventListener('pointerup',()=>bowHeld=false);
  /* claude.ai 안에서는 게임 화면을 한 번 눌러야 키 입력이 들어온다: 초점이 밖에 있으면 알려 준다 */
  const focusHint=document.createElement('div');focusHint.className='toast';focusHint.textContent='게임 화면을 한 번 누르면 방향키·WASD로 걸을 수 있어요';focusHint.style.cssText='position:fixed;left:50%;bottom:118px;transform:translateX(-50%);z-index:60;pointer-events:none';focusHint.hidden=true;document.body.append(focusHint);
  const syncFocus=()=>{focusHint.hidden=!entered||document.hasFocus()||!matchMedia('(pointer:fine)').matches;};window.addEventListener('blur',syncFocus);window.addEventListener('focus',syncFocus);
}
function pick(e){const r=renderer.domElement.getBoundingClientRect();raycaster.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);
  const hits=raycaster.intersectObjects([world.pickRoot,...npcs.map(n=>n.actor.root),cat.root],true);
  for(const hit of hits){let o=hit.object,pick=null,npc=null,isCat=false;while(o){pick ||=o.userData.pick;npc ||=o.userData.npc;isCat ||=o.userData.cat;o=o.parent;}if(npc){talkNpc(npc);return;}if(isCat){approachCat();return;}if(pick?.kind==='spot'){const spot=world.spots[pick.id];if(spot)walkTo(spot,()=>interact(pick.id));return;}if(pick?.kind==='lantern'){showWish(hit.instanceId??0);return;}}
  const ground=world.raycastGround(raycaster.ray);if(ground){walkTo(ground);fx.ripple(v3(ground.x,ground.y+.03,ground.z),{radius:.35,duration:.6});}
}
function escape(){if(death){leaveDeath();return;}if(modal.current){if(modal.current.closable===false){if(mode==='rest'||mode==='exit'){modal.close();lastInput=performance.now();setMode('wander');}return;}modal.close();return;}if(propMode){closeProp();return;}if(fireMode){stopFire();return;}if(mode!=='wander'&&entered){stopActivity();return;}stopWalk();}

function updateCamera(dt,instant=false){if(!player)return;const p=player.root.position,zone=world.zoneAt(p.x,p.z),inside=zone==='hall'?'hall':zone==='chamber'?'mujang':zone==='tea'?'tea':null;world.setCutaway(inside);
  const anchor=p.clone().add(v3(0,.78*ACTOR-seatOffset*.2,0));let target=anchor.clone(),position,fov=50,arm=false;if(inside==='hall')target.y+=.9;/* 대웅전 안: 불상이 화면 위로 잘리지 않게 어른 눈높이에서 본다 */
  if(fireMode){const s=fireMode.seat,yaw=s.yaw+fireMode.angle,forward=v3(Math.sin(yaw),0,Math.cos(yaw)),left=v3(Math.cos(yaw),0,-Math.sin(yaw));position=v3(s.x,world.heightAt(s.x,s.z)+1.45,s.z).addScaledVector(forward,-2.1).addScaledVector(left,.95);target=world.fireCenter.clone().add(v3(0,.5,0));fov=42;}
  else if(cinema){position=cinema.position.clone();target=cinema.target.clone();fov=cinema.fov||45;}
  else{const d=Math.min(cameraDistance,inside?3.4:14);position=target.clone().add(v3(Math.sin(cameraYaw)*Math.cos(cameraPitch)*d,Math.sin(cameraPitch)*d,Math.cos(cameraYaw)*Math.cos(cameraPitch)*d));position.y=Math.max(position.y,world.heightAt(position.x,position.z)+.5);arm=!inside;}
  if(cameraTween){const t=ease((elapsed-cameraTween.start)/cameraTween.duration);position.lerpVectors(cameraTween.position,position,t);target.lerpVectors(cameraTween.look,target,t);fov=THREE.MathUtils.lerp(cameraTween.fov,fov,t);if(t>=1)cameraTween=null;}
  const smoothing=instant?1:1-Math.exp(-dt*8);cameraPos.lerp(position,smoothing);cameraLook.lerp(target,smoothing);
  // Spring arm on the smoothed pose, so smoothing can't carry the camera back through a wall, roof or the pagoda: snap in, ease out.
  // Never nearer than .25 m to the look point; the player is hidden while the camera is nearly inside them.
  const len=cameraLook.distanceTo(cameraPos),hit=arm&&len>1e-6?cameraHit(world.cameraBlockers,cameraLook,cameraPos):1,want=hit<1?Math.max(hit-.35/len,Math.min(1,.25/len)):1;
  cameraArm=instant||want<cameraArm?want:cameraArm+(want-cameraArm)*(1-Math.exp(-dt*2.5));
  camera.position.lerpVectors(cameraLook,cameraPos,cameraArm);
  if(cameraArm<.999)camera.position.y=Math.max(camera.position.y,world.heightAt(camera.position.x,camera.position.z)+.65);
  player.root.visible=camera.position.distanceTo(anchor)>.6;
  camera.lookAt(cameraLook);if(Math.abs(camera.fov-fov)>.01){camera.fov=fov;camera.updateProjectionMatrix();}
}
function updateMovement(dt){if(!player||!(mode==='wander'||(mode==='death'&&path.length))||modal.current||propMode||busy)return;const p=player.root.position;let dx=0,dz=0;const forward=(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0),right=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0);
  if(forward||right){dx=-Math.sin(cameraYaw)*forward+Math.cos(cameraYaw)*right;dz=-Math.cos(cameraYaw)*forward-Math.sin(cameraYaw)*right;const l=Math.hypot(dx,dz);dx=dx/l*WALK*dt;dz=dz/l*WALK*dt;}
  else if(path.length){const target=path[0],d=dist(p,target);if(d<.08){path.shift();if(!path.length){arrive();return;}}else{const speed=Math.min(WALK*dt,d);dx=(target.x-p.x)/d*speed;dz=(target.z-p.z)/d*speed;}}
  const oldX=p.x,oldZ=p.z;nav.slide(p,dx,dz);p.y=world.heightAt(p.x,p.z);const moved=Math.hypot(p.x-oldX,p.z-oldZ);walking=moved>.0001;
  if(walking){const targetYaw=Math.atan2(p.x-oldX,p.z-oldZ);player.root.rotation.y+=THREE.MathUtils.euclideanModulo(targetYaw-player.root.rotation.y+Math.PI,Math.PI*2)-Math.PI;setPose('walk');player.setSpeed(moved/dt);sendPresence();}else{setPose('idle');player.setSpeed(0);if(path.length&&(dx||dz)){stopWalk();toast('이 길은 막혀 있어요.');}}
}

function updateNPCs(dt){
  const p=player.root.position;
  for(const n of npcs){const a=n.actor;if(n.role==='novice'){if(service){const s=world.spots.bell;if(moveRoute(a,s,.85,dt)&&elapsed-serviceBell>12){serviceBell=elapsed;world.strikeBell()?.then(()=>audio.bell());}}else if(n.pause>elapsed)a.setPose('sweep');else{const points=world.paths.novice,target=points[n.pathIndex%points.length];if(moveRoute(a,target,.65,dt)){n.pathIndex++;n.pause=elapsed+3.5;}}}
    if(n.role==='abbot'){const visit=fireMode&&world.nightFactor>.5&&elapsed-fireMode.start>35&&elapsed-fireMode.start<155&&!service;if(!visit)n.seat=undefined;else if(n.seat===undefined)n.seat=['fire-se','fire-sw','fire-s'].map(id=>world.spots[id]).find(s=>s&&s!==fireMode.seat&&!peers.some(p=>p.m==='fire'&&dist(p,s)<.8))||null;const s=visit&&n.seat;if(s){if(moveRoute(a,s,1,dt)){a.root.position.y=world.heightAt(s.x,s.z)+.42;a.root.rotation.y=s.yaw;a.setPose('sit');}}else if(dist(a.root.position,n.home)>.2){moveRoute(a,n.home,1,dt);}else{a.root.position.copy(n.home);a.root.rotation.y=n.yaw;a.setPose(service?'moktak':'zen');}}
    if(dist(a.root.position,p)<4&&elapsed-n.lastGreeting>25&&mode==='wander'){n.lastGreeting=elapsed;a.play('gassho');}a.update(dt);
  }
  if(fireMode&&elapsed-fireMode.start>20){const target=fireMode.catSpot||world.catFireSpot;if(moveRoute(cat,target,1.4,dt)){cat.setPose('sleep');cat.root.rotation.y=fireMode.catYaw??.7;}}
  else if(cat.pause>elapsed)cat.setPose('sit');else{const route=world.paths.cat,target=route[cat.pathIndex%route.length];if(moveRoute(cat,target,.75,dt)){cat.pathIndex++;cat.pause=elapsed+5;}}
  cat.update(dt);
}
/* shortcut: route is planned once per target and ignores moving players; replan on a timer if NPCs snag */function moveRoute(actor,target,speed,dt){if(!target)return true;if(actor.routeTarget!==target){actor.routeTarget=target;actor.route=[...nav.path(actor.root.position,target),target];}while(actor.route.length>1&&dist(actor.root.position,actor.route[0])<.12)actor.route.shift();return moveActor(actor,actor.route[0],speed,dt)&&actor.route.length===1;}
function moveActor(actor,target,speed,dt){if(!target)return true;const p=actor.root.position,d=dist(p,target);if(d<.12){actor.setSpeed(0);return true;}const s=Math.min(d,speed*dt);p.x+=(target.x-p.x)/d*s;p.z+=(target.z-p.z)/d*s;p.y=world.heightAt(p.x,p.z);actor.root.rotation.y=Math.atan2(target.x-p.x,target.z-p.z);actor.setSpeed(speed);actor.setPose('walk');return false;}
function talkNpc(role){const n=npcs.find(x=>x.role===role);const phrases={abbot:Math.random()>.5?'편히 앉았다 가세요.':'절은 숫자보다 마음이에요.',tea:'차 한 잔 하고 가요.',guide:'무상당은 삶을 한 번 정리해 보는 곳이에요.',novice:'낙엽이 많아요. 같이 쓸어요.'};const line=phrases[role],l=n&&labels.find(x=>x.actor===n.actor);if(l){l.node.textContent=line;l.node.classList.add('say');l.sayUntil=elapsed+3;}if(!l||role==='guide'||role==='tea')toast(line,role==='guide'?deathIntro:role==='tea'?openTea:undefined,role==='guide'?'임종체험 시작하기':'스님과 차담',6000);n?.actor.play('gassho');}
function updateLabels(){const ww=innerWidth,hh=innerHeight,visible=entered&&mode==='wander'&&!propMode;for(const l of labels){if(l.sayUntil&&elapsed>l.sayUntil){l.sayUntil=0;l.node.textContent=l.name;l.node.classList.remove('say');}const p=l.actor.headPos?.()||l.actor.root.position.clone().add(v3(0,.8,0));p.y+=.25;const distance=dist(l.actor.root.position,player.root.position);p.project(camera);const show=visible&&p.z>-1&&p.z<1&&(l.kind!=='npc'||l.sayUntil>0||distance<6)&&(l.kind!=='peer'||distance<18)&&Math.abs(p.x)<1.1&&Math.abs(p.y)<1.1;l.node.hidden=!show;if(show)l.node.style.transform=`translate(${(p.x*.5+.5)*ww}px,${(-p.y*.5+.5)*hh}px) translate(-50%,-100%)`;}updateSpotTags(ww,hh,visible);}
// 화면에 보이는 가까운 체험 자리 5곳 위에 누를 수 있는 표시를 띄운다(바로 옆 자리는 아래 F 단추가 대신한다)
function updateSpotTags(ww,hh,visible){
  if(!spotTags)spotTags=experiences.filter(x=>x[5]&&world.spots[x[4]]).map(([id,,,,spot,label,range])=>{const s=world.spots[spot],node=el('button',{class:'spot-tag',type:'button','aria-label':`${label} 하러 가기`,onclick:()=>startExperience(id)},label);node.hidden=true;$('#names').append(node);return {spot,range,node,pos:v3(s.x,(world.heightAt(s.x,s.z)||0)+2,s.z)};});
  const on=[];if(visible&&!modal.current&&!busy)for(const t of spotTags){const d=dist(t.pos,player.root.position);if(d>=t.range||t.spot===nearestSpot?.id)continue;const p=t.pos.clone().project(camera);if(p.z>-1&&p.z<1&&Math.abs(p.x)<.94&&Math.abs(p.y)<.86)on.push({t,d,p});}
  on.sort((a,b)=>a.d-b.d).splice(5);
  for(const t of spotTags){const o=on.find(o=>o.t===t);if(t.node.hidden===!!o)t.node.hidden=!o;if(!o)continue;
    /* 좁은 화면에서도 표시 전체가 화면 안에 들도록 실제 폭으로 가로 위치를 묶고, 좌표가 바뀔 때만 다시 쓴다 */
    const w=t.w||(t.w=t.node.offsetWidth),x=Math.min(Math.max((o.p.x*.5+.5)*ww,w/2+6),ww-w/2-6),tf=`translate(${x|0}px,${(-o.p.y*.5+.5)*hh|0}px) translate(-50%,-100%)`;if(t.tf!==tf)t.node.style.transform=t.tf=tf;}}

function frame(now){raf=0;if(document.hidden)return;raf=requestAnimationFrame(frame);if(mode==='rest'&&now-lastRender<100)return;const raw=(now-lastFrame)/1000;lastFrame=now;lastRender=now;const dt=clamp(raw,0,.1);elapsed+=dt;
  try{for(let i=tweens.length-1;i>=0;i--){const t=tweens[i],f=clamp((elapsed-t.start)/t.sec,0,1);try{t.fn(f);}catch(e){report('tween',e);}if(f===1){tweens.splice(i,1);t.resolve();}}
    updateMovement(dt);updateActivities(dt);updateNPCs(dt);player.update(dt);world.update(dt,elapsed,player.root.position);fx.update(dt,elapsed);updateRemote(dt);updateCamera(dt);updateLabels();updateProp(dt);
    if(elapsed-lastSky>.25){lastSky=elapsed;let hour=currentHour();if(fireMode&&fireMode.nightTransition)hour=THREE.MathUtils.lerp(17.8,21.5,clamp((elapsed-fireMode.start)/6,0,1));world.setTime(hour);const zone=world.zoneAt(player.root.position.x,player.root.position.z),env=`${zone}:${Math.floor(hour*4)}`;if(entered&&env!==lastEnvironment){lastEnvironment=env;audio.setEnvironment({zone,hour,nightFactor:world.nightFactor});}audio.fire(dist(player.root.position,world.fireCenter)<18,clamp(fire.level/(1+dist(player.root.position,world.fireCenter)*.15),0,1));}
    if(elapsed-lastUi>.2){lastUi=elapsed;updateContext();updateModeText();}if(elapsed-lastSchedule>5){lastSchedule=elapsed;updateSchedule();}if(Date.now()-lastVisitSave>60000)saveVisit();
    if(entered&&mode==='wander'&&!modal.current&&!path.length&&performance.now()-lastInput>300000)restScreen();
    renderer.render(scene,camera);if(propMode)renderProp();if(mode==='rest')fps=1/Math.max(raw,.1);
    if(mode!=='rest'&&raw<1&&raw>0){perfTime+=raw;perfTotal+=raw*1000;perfFrames++;if(perfTime>=3){fps=perfFrames/perfTime;const average=perfTotal/perfFrames;if(settings.quality==='auto'&&average>22){if(pixelRatio>.75){pixelRatio=Math.max(.75,pixelRatio-.25);renderer.setPixelRatio(pixelRatio);}else if(shadows){world.setShadows(false);shadows=false;}}perfTime=perfTotal=perfFrames=0;}}
  }catch(e){report('frame',e);}
}

boot().catch(fail);

// Activities use one cancellation token, so a late animation cannot reopen a dismissed mode.
function stopActivity(){actionToken++;if(activeSweep!==null){world.setLeafPile(activeSweep,leafAmounts[activeSweep]);activeSweep=null;}busy=false;bowHeld=spaceHeld=false;stopWalk();keys.clear();modal.close();closeProp();if(fireMode)stopFire();if(death){stopDeath();return;}if(zen){audio.setDuck(1);zen=null;}if(tea){world.teaCupVisible(false);world.teaPour(0);tea=null;}sitting=null;tapdori=null;player.hold(broom?'broom':null);player.setExpression('normal');setPose('idle');seatOffset=0;player.root.position.y=world.heightAt(player.root.position.x,player.root.position.z);cinema=null;hideModeBar();showHud(true);setMode('wander');cameraTransition(.8);audio.purr(false);}
async function goImmediate(id){if(!world)return false;if(!entered)enter();stopActivity();const p=world.spots[id]||world.places.find(p=>p.id===id);if(!p)return false;if(!await fadeTo(p))return false;sendPresence(true);return true;}
async function interact(id){if(death){if(['portrait-seat','letter-desk','robe-rack','coffin'].includes(id))return deathStep();return;}if(mode!=='wander')return;const s=world.spots[id];if(!s)return;
  if(id.startsWith('fire-'))return startFire(id);if(id==='fork'){toast("왼쪽 일주문은 템플스테이 마당으로, 오른쪽 무상문은 임종체험관 '무상당'으로 이어져요.",null,null,10000);return;}
  if(id==='mujang-start')return deathIntro();if(id==='incense')return incense();if(id==='bell')return ringBell();if(id==='pagoda')return startTapdori();if(id==='broom')return takeBroom();if(id.startsWith('leaf-'))return sweep(Number(id.split('-')[1]));if(id==='lantern-desk')return openLantern();if(id==='tea-seat')return openTea();if(id.startsWith('cushion-'))return openZen(s);if(['coffin','portrait-seat','letter-desk','robe-rack'].includes(id))return deathIntro();sit(s);
}
function act(name){const actions={bow,gassho,bell:ringBell,incense,tapdori:startTapdori,zen:()=>openZen(closestCushion()),broom:takeBroom,sweep:()=>sweep(closestLeaf()),sit:()=>sit(nearestSpot||world.spots['bench-ginkgo']),photo,pet};return actions[name]?.();}
function updateContext(){if(!entered||!world)return;const p=player.root.position;nearestSpot=null;if(mode==='wander'&&!busy&&!propMode){let nearest=Infinity;for(const s of Object.values(world.spots)){if(s.id.startsWith('leaf-')&&(!broom||leafAmounts[Number(s.id.split('-')[1])]===0))continue;const d=dist(p,s);if(d<=s.r&&d<nearest){nearest=d;nearestSpot=s;}}}
  const button=$('#context-btn');button.hidden=!nearestSpot;if(nearestSpot)button.textContent=`F ${nearestSpot.label}`;
  const bows=record.today.bows||0;$('#bow-count').textContent=world.zoneAt(p.x,p.z)==='hall'?`108배 ${bows&&bows%108===0?108:bows%108}/108 · 오늘 ${bows}배`:`오늘 ${bows}배 · 모두 ${record.totals.bows||0}배`;
  if(world.placeAt(p.x,p.z)==='fork'&&!record.forkSeen){record.forkSeen=true;interact('fork');save();}
}
