function initPropRenderer(){if(propRenderer)return;propRenderer=new THREE.WebGLRenderer({alpha:true,antialias:true});propRenderer.outputColorSpace=THREE.SRGBColorSpace;propRenderer.toneMapping=THREE.ACESFilmicToneMapping;propRenderer.setPixelRatio(Math.min(devicePixelRatio,1.5));propScene=new THREE.Scene();propScene.add(new THREE.HemisphereLight(0xfff1d7,0x42301b,3));const light=new THREE.DirectionalLight(0xffd3a1,4);light.position.set(-3,5,6);propScene.add(light);propCamera=new THREE.PerspectiveCamera(38,1,.01,30);propCamera.position.set(0,1.1,4);propCamera.lookAt(0,0,0);resizeProp();}
