  /* 염주: 끄는 만큼 구슬이 따라 움직이고 구슬 한 칸(캔버스 높이의 약 7%)마다 한 알, 끌지 않고 누르기만 해도 한 알 */
  canvas.onpointerdown=e=>{held=true;sy=e.clientY;acc=0;got=0;canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!held||name!=='beads')return;acc+=e.clientY-sy;sy=e.clientY;const px=Math.max(16,canvas.clientHeight*.068);while(Math.abs(acc)>=px){const d=Math.sign(acc);acc-=d*px;got++;advanceBeads(d);}};canvas.onpointerup=()=>{if(!held)return;held=false;if(name==='moktak')strikeMoktak();else if(!got)advanceBeads(1);};canvas.onpointercancel=()=>{held=false;};
  /* 휠: 한 번 굴리기(쉬었다 다시 굴림)나 큰 한 칸은 늘 한 알, 트랙패드처럼 잘게 이어지는 움직임은 100px마다 한 알 더 */
